cards.solution:
import java.math.BigDecimal;
import java.math.RoundingMode;

public class Main {
    public static void main(String[] args) {
        BigDecimal harga = new BigDecimal("45000");
        int jumlah = 3;
        BigDecimal subtotal = harga.multiply(new BigDecimal(jumlah));
        BigDecimal ppn = subtotal.multiply(new BigDecimal("0.11")).setScale(0, RoundingMode.HALF_UP);
        BigDecimal total = subtotal.add(ppn);
        System.out.println(subtotal);
        System.out.println(ppn);
        System.out.println(total);
    }
}

